#!/usr/bin/env python3
"""x-mutable: regenerate proj/XMut/ECheckZ.lean from the vendored proj/Work/Gauge/ECheck.lean (Nil Mamano's E7 check,
via Ryan Shea's complex588 tree): the replay gItems -> gItemsZ, kinds okA/okB -> okAZ/okBZ, names ...Z.
usage: make_echeckZ.py <proj/Work/Gauge/ECheck.lean> <proj/XMut/ECheckZ.lean>"""
import sys
HDR = "import Work.Gauge.ECheck\nimport XMut.ScalarZ\n\n/-!\n# x-mutable (13 Oct 2026): the E7 kernel check with mutable sources (`eCheckZ`)\n\nNil Mamano's `eCheck` / `ERun` / `eCheck_sound` (`Work/Gauge/ECheck.lean`, mirror of Jacob Sussman's `yCheck`), word\nfor word, with the replay `gItemsZ` (gate kinds `okAZK` / `okBZK`).  E7: a gauged slot never reaches a target.\nGenerated by text substitution (x-mutable/tools/make_echeckZ.py).  No `sorry`.\n-/\n\nset_option linter.unusedSectionVars false\nset_option linter.unusedVariables false\nset_option linter.unusedSimpArgs false\nset_option linter.deprecated false\n\nnamespace GS\nopen SSC GXD OAI.PowerSaving OAI.PowerSaving.Binary OAI.PowerSaving.RAM OAI.PowerSaving.SS\n  OAI.PowerSaving.CB OAI.PowerSaving.CR Finset Matrix\n\n"
ECK = '/-- **The E7 check, sources mutable** (one evaluation): as `eCheck`, with the mutable-source gate kinds. -/\nnoncomputable def eCheckZ (c : Raw) (p : SPar) (gl : List Nat) : Bool :=\n  gPre c p 0 gl.length fun v2 nr _ tm K m2 =>\n    guard (incK nr gl v2) (guard (Nat.ble (Nat.succ p.us) (Nat.pow 2 (Nat.sub p.sw 1)))\n      (guard (Nat.ble (Nat.succ p.us) 2147483648)\n        (forceN (List.length c.ret) fun rl =>\n          gInitL p.sw p.us gl 0 (Trie.mk p.d) fun tr0 =>\n            gItemsZ c p v2 nr tm K m2 rl (prog c) tr0 fun tr3 =>\n              gFin p.sw K m2 p.uy c.v 0 0 tr3 c.v 0)))\n\n'
REPS = [("def ERun ","def ERunZ "),("ItemsRun c p gl.length (prog c) a0 b","ItemsRunZ c p gl.length (prog c) a0 b"),
("theorem ERun.of_check {c : Raw} {p : SPar} {gl : List Nat} (h : eCheck c p gl = true) : ERun c gl := by\n  unfold eCheck at h",
 "theorem ERunZ.of_check {c : Raw} {p : SPar} {gl : List Nat} (h : eCheckZ c p gl = true) : ERunZ c gl := by\n  unfold eCheckZ at h"),
("gItems_sound c p 0 gl.length hp (prog c) t0 _ hI0 hk","gItemsZ_sound c p 0 gl.length hp (prog c) t0 _ hI0 hk"),
("theorem ERun.ycol {c : Raw} (hv : 0 < c.v) {gl : List Nat} (h : ERun c gl)","theorem ERunZ.ycol {c : Raw} (hv : 0 < c.v) {gl : List Nat} (h : ERunZ c gl)"),
("ItemsRun_split c p gl.length","ItemsRunZ_split c p gl.length"),
("ItemsRun_cA c p gl.length","ItemsRunZ_cA c p gl.length"),("ItemsRun_cB c p gl.length","ItemsRunZ_cB c p gl.length"),
("okA c t s = true","okAZ c t s = true"),("okB c t s = true","okBZ c t s = true"),
("(okA_spec ho)","(okAZ_spec ho)"),("(okB_spec ho)","(okBZ_spec ho)"),
("(U c p) (okA c) (fun _ => true)","(U c p) (okAZ c) (fun _ => true)"),("(U c p) (okB c) (fun _ => true)","(U c p) (okBZ c) (fun _ => true)"),
("/-- **E7, the kernel check.** -/\ntheorem eCheck_sound {c : Raw} {p : SPar} {gl : List Nat} (hv : 0 < c.v) (h : eCheck c p gl = true)",
 "/-- **E7, the kernel check, sources mutable.** -/\ntheorem eCheckZ_sound {c : Raw} {p : SPar} {gl : List Nat} (hv : 0 < c.v) (h : eCheckZ c p gl = true)"),
("ERun.ycol hv (ERun.of_check h) q hq S","ERunZ.ycol hv (ERunZ.of_check h) q hq S")]
src = open(sys.argv[1]).read()
body = src[src.index("/-- **An accepted E7 replay.** -/"):src.index("end GS")]
for a, b in REPS:
    assert body.count(a) >= 1, a
    body = body.replace(a, b)
open(sys.argv[2], "w").write(HDR + ECK + body + "end GS\n\n#print axioms GS.eCheckZ_sound\n")
